insert into public.platform_settings (id, settings) values (true, '{"currency":"NGN","timezone":"Africa/Lagos","holdMinutes":10,"claimWindowHours":72,"acceptanceHours":4,"commissionBps":1000,"buyerFeeBps":0,"taxIncludedInPrices":true,"maxAdvanceDays":90,"adjustmentApprovalThreshold":5000000}'::jsonb) on conflict (id) do update set settings = excluded.settings;
insert into public.vendors (id, slug, name, tagline, about, logo_initials, logo_color, cover_image, status, verified, zones, operating, fulfilment, categories, business_type, city, response_hours, featured, joined_at, return_policy, delivery_policy) values
('ven_bloom', 'bloom-and-bisi', 'Bloom & Bisi', 'Hand-tied flowers, delivered the same day across Lagos.', 'Bisi started arranging flowers for friends'' weddings in Surulere in 2017. Today her studio sources stems from growers in Jos and Plateau every week and ties every bouquet by hand on the day it leaves.', 'BB', 'oklch(0.62 0.13 10)', '/media/v/flower-shop.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":300000,"leadDays":0},{"zoneId":"lagos-mainland","fee":300000,"leadDays":0},{"zoneId":"lekki-ajah","fee":400000,"leadDays":0}]'::jsonb, '{"days":[0,1,2,3,4,5,6],"openHour":7,"closeHour":19,"cutoffHour":14,"blackoutDates":[],"dailyCapacity":40,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['flowers']::text[], 'limited_company', 'Lagos', 1, true, '2025-08-07T11:59:11.201Z', 'Fresh flowers can''t be returned. If your bouquet arrives damaged, tell us within 24 hours with a photo and we''ll replace it.', 'Same-day delivery for orders confirmed before 2pm. Our own riders deliver between 10am and 7pm.'),
('ven_hamper', 'the-hamper-room', 'The Hamper Room', 'Generous hampers and treat boxes, packed to order.', 'A small team in Ikeja building hampers around Nigerian-made snacks, single-origin coffee from Mambilla and chocolate from Ondo cocoa. Every box is packed by hand and checked twice.', 'HR', 'oklch(0.55 0.1 60)', '/media/v/gifts-dark.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":350000,"leadDays":0},{"zoneId":"lagos-mainland","fee":350000,"leadDays":0},{"zoneId":"lekki-ajah","fee":450000,"leadDays":0},{"zoneId":"abuja-central","fee":750000,"leadDays":1},{"zoneId":"port-harcourt","fee":800000,"leadDays":2}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":13,"blackoutDates":[],"dailyCapacity":30,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['hampers']::text[], 'limited_company', 'Lagos', 2, true, '2025-12-05T11:59:11.201Z', 'Unopened, non-perishable hampers can be returned within 7 days of delivery. Perishable items are non-returnable.', 'Lagos orders before 1pm arrive the same day. Abuja and Port Harcourt are delivered by our courier partner in 1–2 days.'),
('ven_kemi', 'kemi-bakes', 'Kemi Bakes', 'Celebration cakes baked fresh for your date.', 'Kemi bakes every cake to order in her Yaba kitchen. Butter, real chocolate and no shortcuts — so please give her a day''s notice.', 'KB', 'oklch(0.55 0.13 30)', '/media/v/baking.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":350000,"leadDays":0},{"zoneId":"lagos-mainland","fee":350000,"leadDays":0},{"zoneId":"lekki-ajah","fee":500000,"leadDays":0}]'::jsonb, '{"days":[2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":12,"blackoutDates":[],"dailyCapacity":8,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['cakes']::text[], 'sole_proprietor', 'Lagos', 3, false, '2026-04-24T11:59:11.201Z', 'Cakes are baked to order and can''t be returned. If something isn''t right on arrival, message us the same day.', 'Cakes need at least 24 hours. Delivered in a temperature-safe box between 10am and 6pm.'),
('ven_adire', 'adire-home', 'Adire Home Co.', 'Candles, ceramics and soft things for slow evenings.', 'Adire Home works with ceramicists in Abeokuta and candle makers in Ibadan. Everything is small-batch, and most of it is made within a day''s drive of our studio.', 'AH', 'oklch(0.45 0.08 250)', '/media/v/living-room.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":300000,"leadDays":0},{"zoneId":"lagos-mainland","fee":300000,"leadDays":0},{"zoneId":"lekki-ajah","fee":400000,"leadDays":0},{"zoneId":"abuja-central","fee":650000,"leadDays":1}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['home']::text[], 'partnership', 'Lagos', 2, true, '2026-01-14T11:59:11.201Z', 'Return unused items in original packaging within 14 days. Personalised pieces can''t be returned unless they arrive damaged.', 'Ready in a day. Lagos delivery by our riders; Abuja next day by courier.'),
('ven_gold', 'gold-thread', 'Gold Thread Jewellery', 'Fine jewellery, engraved by hand in Lagos.', 'A family jeweller on Lagos Island since 1998. Every piece is hallmarked, and engraving is done in-house by Uncle Femi, who has been doing it for twenty years.', 'GT', 'oklch(0.6 0.11 80)', '/media/v/jewellery.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":400000,"leadDays":0},{"zoneId":"lagos-mainland","fee":400000,"leadDays":0},{"zoneId":"lekki-ajah","fee":500000,"leadDays":0},{"zoneId":"abuja-central","fee":800000,"leadDays":1},{"zoneId":"port-harcourt","fee":800000,"leadDays":1}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":14,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'courier', array['jewellery','fashion']::text[], 'limited_company', 'Lagos', 2, true, '2025-09-16T11:59:11.201Z', 'Return unworn, non-engraved jewellery within 14 days. Engraved pieces are final sale unless we made an error.', 'Insured courier delivery with signature on arrival.'),
('ven_nest', 'nest-and-nook', 'Nest & Nook', 'Kitchen essentials couples actually use.', 'The wedding registry favourite. We stock appliances with local warranties and test every unit before it leaves the warehouse in Lekki.', 'NN', 'oklch(0.5 0.08 160)', '/media/v/kitchen.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":450000,"leadDays":0},{"zoneId":"lagos-mainland","fee":450000,"leadDays":0},{"zoneId":"lekki-ajah","fee":450000,"leadDays":0},{"zoneId":"abuja-central","fee":950000,"leadDays":2}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":12,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'courier', array['kitchen']::text[], 'limited_company', 'Lagos', 3, false, '2026-03-05T11:59:11.201Z', 'Unopened appliances can be returned within 14 days. Opened appliances are covered by the manufacturer''s 12-month warranty.', 'Delivered by courier within 1–2 days in Lagos, 2–3 days in Abuja.'),
('ven_little', 'little-ones', 'Little Ones Co.', 'Soft, safe gifts for new arrivals.', 'Organic cotton, non-toxic toys and practical bundles chosen by two mums in Abuja who were tired of gifts that went straight into a cupboard.', 'LO', 'oklch(0.6 0.09 200)', '/media/v/baby.webp', 'approved', true, '[{"zoneId":"abuja-central","fee":300000,"leadDays":0},{"zoneId":"lagos-island","fee":700000,"leadDays":1},{"zoneId":"lagos-mainland","fee":700000,"leadDays":1},{"zoneId":"lekki-ajah","fee":800000,"leadDays":1}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['baby']::text[], 'sole_proprietor', 'Abuja', 2, false, '2026-05-14T11:59:11.201Z', 'Unused items in original packaging can be returned within 14 days.', 'Same-day in Abuja Central before 3pm. Lagos delivery next day by courier.'),
('ven_leaf', 'leaf-and-clay', 'Leaf & Clay', 'Easy-going plants in handmade pots.', 'Plants that forgive a missed watering, potted in terracotta made in Ilorin. We include care cards with every plant.', 'LC', 'oklch(0.5 0.1 140)', '/media/v/garden.webp', 'approved', false, '[{"zoneId":"abuja-central","fee":250000,"leadDays":0}]'::jsonb, '{"days":[1,2,3,4,5],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['plants']::text[], 'sole_proprietor', 'Abuja', 4, false, '2026-08-02T11:59:11.201Z', 'Living plants can''t be returned. If a plant arrives damaged, we''ll replace it.', 'Abuja Central only, Monday to Friday.'),
('ven_ink', 'ink-and-page', 'Ink & Page', 'Books and stationery for people who still write things down.', 'An independent bookshop in Yaba with a stationery counter. We''ll hand-letter a name on any notebook.', 'IP', 'oklch(0.35 0.03 260)', '/media/v/library.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":250000,"leadDays":0},{"zoneId":"lagos-mainland","fee":250000,"leadDays":0},{"zoneId":"lekki-ajah","fee":350000,"leadDays":0}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'vendor_delivery', array['books']::text[], 'sole_proprietor', 'Lagos', 2, false, '2026-03-25T11:59:11.201Z', 'Books in new condition can be returned within 14 days. Personalised notebooks are final sale.', 'Delivered by our riders the next working day.'),
('ven_glow', 'glow-ritual', 'Glow Ritual', 'Clean skincare made with shea from Kwara.', 'Small-batch oils, serums and body care. Every product is dermatologically tested, and we never make medical claims about what it''ll do.', 'GR', 'oklch(0.6 0.12 70)', '/media/v/serum.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":300000,"leadDays":0},{"zoneId":"lagos-mainland","fee":300000,"leadDays":0},{"zoneId":"lekki-ajah","fee":400000,"leadDays":0},{"zoneId":"abuja-central","fee":600000,"leadDays":1},{"zoneId":"port-harcourt","fee":600000,"leadDays":1}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'courier', array['beauty']::text[], 'limited_company', 'Lagos', 2, true, '2026-02-13T11:59:11.201Z', 'Unopened products can be returned within 14 days.', 'Courier delivery within 1–2 days.'),
('ven_leather', 'lagos-leather', 'Lagos Leather Co.', 'Bags and accessories built to be used every day.', 'Full-grain leather, stitched in our workshop in Surulere. We''ll emboss initials on any bag.', 'LL', 'oklch(0.45 0.1 40)', '/media/v/backpack.webp', 'approved', true, '[{"zoneId":"lagos-island","fee":350000,"leadDays":0},{"zoneId":"lagos-mainland","fee":350000,"leadDays":0},{"zoneId":"lekki-ajah","fee":450000,"leadDays":0},{"zoneId":"abuja-central","fee":700000,"leadDays":1}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'courier', array['fashion']::text[], 'limited_company', 'Lagos', 3, false, '2026-06-13T11:59:11.201Z', 'Return unused items within 14 days. Embossed items are final sale.', 'Courier delivery within 1–2 days.'),
('ven_pending', 'aso-and-co', 'Aso & Co.', 'Hand-woven aso-oke accessories.', 'A weaving collective from Iseyin making aso-oke fans, clutches and gele.', 'AC', 'oklch(0.5 0.12 300)', '/media/v/gifts-dark.webp', 'under_review', false, '[{"zoneId":"lagos-island","fee":400000,"leadDays":0},{"zoneId":"lagos-mainland","fee":400000,"leadDays":0},{"zoneId":"lekki-ajah","fee":500000,"leadDays":0}]'::jsonb, '{"days":[1,2,3,4,5,6],"openHour":8,"closeHour":19,"cutoffHour":15,"blackoutDates":[],"dailyCapacity":25,"deliveryWindow":[10,19]}'::jsonb, 'courier', array['fashion']::text[], 'partnership', 'Iseyin', 4, false, '2026-09-28T11:59:11.201Z', 'Returns within 7 days on unused items.', 'Courier from Iseyin, 2–3 days.')
