insert into public.products (id, vendor_id, slug, title, summary, description, included, dimensions, images, category, occasions, interests, status, prep_hours, perishable, highly_customised, return_eligible, personalisation, wrapping, sponsored, editorial_score, moderation_note, created_at) values
